  it("provider 无可用 model 时不调用模型流", () => {
    expect(seen5.calls).toHaveLength(0);
    expect(r5.meta).toMatchObject({
      ok: false,
      error: "无可用的已注册 provider/model（须先在 dsh 注册适配器路由）",
    });
  });
});

