    injectedHasDirBucket = textOf(seen.calls[0]!.messages[0].content[0]).includes(
      JSON.stringify(s.byDirectory[0]),
    );
    await tracker.dispose();
    // dir 键防御（与 provider/model 名同口径）：控制字符剥离 + 80 字符截断
    const hostile = buildStatsSnapshot({
      period: "daily",
