  it("控制字符剥除 + 截断 80 形态（剥后残留字面字符保留）", () => {
    const hostileDir = allDirs.find((d) => d.startsWith("x"));
    expect(
      hostileDir !== undefined && hostileDir.length <= 80 && !/[\u0000-\u001f]/.test(hostileDir),
