    it(`报告产物（${name}）无原始控制字符（排版 \\n/\\t 除外）`, () => {
      const artifact = getArtifact();
      // 目录键不携带的排版性换行/制表除外（meta.json 为缩进 2 pretty JSON），其余 C0 控制字符不得出现
      expect(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(artifact)).toBeFalsy();
    });
