  it("产物正文含 basename 目录名（LLM 叙事引用）", () => {
    expect(htmlText.includes("secret-project")).toBeTruthy();
  });

  it("推送已发出", () => {
    expect(sentLen).toBe(1);
  });

  it("推送摘要不含任何路径分隔符（仅周期/窗口/数值）", () => {
    expect(!pushBody.includes("/") && !pushBody.includes("\\")).toBeTruthy();
  });

  it("推送摘要无控制字符", () => {
