  it("directories 持久化 round-trip 一致", () => {
    expect(loadedDirs).toEqual(["proj", "repo"]);
  });

  it("存量配置（无 directories 键）读回 → 默认空数组", () => {
    expect(reloadedDirs).toEqual([]);
  });

  it("存量配置其余字段不受影响", () => {
    expect(reloadedIntact).toBeTruthy();
  });
});

