  it("原字段值经读回不变（中文会话 id/数值逐字段一致）", () => {
    // 原 assert.deepEqual 为 node:assert/strict 的 deepStrictEqual：期望值显式含
    // input/turns: undefined，键在位性属判定一部分，故用 toStrictEqual 保语义不弱化。
    expect(backFields).toStrictEqual([
