        day: DAY0,
        hour: 12,
        input: 22,
        output: 17,
        cacheRead: 0,
        cacheWrite: 0,
        calls: 4,
        turns: 1,
        toolCalls: 0,
      },
    ]);
  });

  it("同 cwd 双 session 归并为恰 1 条（calls 为和）；不同 cwd/未识别桶独立行", () => {
    expect(shardDirs).toEqual([
      {
        v: TREND_ROW_VERSION,
        kind: "dir",
        day: DAY0,
        dir: "shared",
        input: 17,
        output: 12,
        cacheRead: 0,
