  });

  it("item 为数字跳过", () => {
    expect(parseUserAdapters('{"adapters":[42]}')).toEqual([]);
  });

  it("item 为字符串跳过", () => {
    expect(parseUserAdapters('{"adapters":["str"]}')).toEqual([]);
  });

  // id 异型但 length>0：原实现按非字符串丢弃，变异为直通时输出会带数组 id
  it("id 为 length>0 数组拒绝", () => {
