  it("providers 元素全为数组被滤空后条目拒绝", () => {
    expect(
      parseUserAdapters('{"adapters":[{"id":"a","providers":[["x"],[2]],"file":"/f"}]}'),
    ).toEqual([]);
  });

  it("providers 元素为类数组对象被滤空后条目拒绝", () => {
